<template>
  <div class="map-viewport" ref="viewport">
    <div class="pan-surface" ref="surface" :style="surfaceStyle">
      <div
        v-for="t in tiles"
        :key="t.region"
        class="region-tile"
        :style="{
          left: t.x + 'px',
          top: t.y + 'px',
          width: t.w + 'px',
          height: t.h + 'px',
          transform: 'scale(' + t.scale + ')',
          transformOrigin: 'top left',
        }"
      >
        <RegionTile :region="t.region" />
      </div>
      <!-- Itorash slot: Final Boss (Raven Beak) victory indicator. -->
      <div class="itorash-slot" data-region="itorash" :style="itorashStyle">
        <div
          class="final-boss-marker"
          data-testid="final-boss-marker"
          :class="seedBeatable ? 'active' : 'notActive'"
          title="Raven Beak (Final Boss) — lit when the seed is beatable: DNA gate open and final boss path reachable"
        >
          <span class="final-boss-label">Raven Beak</span>
          <span class="final-boss-sublabel">Final Boss</span>
        </div>
      </div>
    </div>
    <div class="zoom-controls panzoom-exclude">
      <button aria-label="Zoom in" class="zoom-btn" @click="zoomIn">+</button>
      <button aria-label="Zoom out" class="zoom-btn" @click="zoomOut">
        &#8722;
      </button>
      <button aria-label="Reset view" class="zoom-btn" @click="resetView">
        &#10227;
      </button>
    </div>
  </div>
</template>

<script>
import Panzoom from "@panzoom/panzoom";
import { mapGetters } from "vuex";
import RegionTile from "@/components/RegionTile.vue";

// Logical surface dimensions — all tile positions are relative to this.
// Sized to contain all tiles with breathing room matching the reference overworld layout.
const SURFACE_W = 3800;
const SURFACE_H = 2700;

// Overworld tile layout approximating the Metroid Dread elevator/region arrangement.
// Fractional center references (cx, cy of logical surface):
//   hanubia  (~0.56, 0.16), ghavoran (~0.11, 0.30), ferenia (~0.54, 0.33),
//   elun     (~0.37, 0.37), dairon   (~0.42, 0.55), cataris  (~0.82, 0.55),
//   burenia  (~0.11, 0.66), artaria  (~0.52, 0.83)
// Top-left = center_frac * SURFACE - half_rendered_size; rendered_size = native * scale.
// scale=1 for all tiles except Elun (scale=0.6).
const TILES = [
  // Upper band — Hanubia (upper center)
  { region: "hanubia", x: 1588, y: 220, w: 1080, h: 423, scale: 1 },
  // Middle-upper band — Ghavoran (far left), Ferenia (center-right), Elun (small, center)
  { region: "ghavoran", x: 0, y: 581, w: 1080, h: 458, scale: 1 },
  { region: "ferenia", x: 1512, y: 653, w: 1080, h: 476, scale: 1 },
  { region: "elun", x: 1082, y: 916, w: 1080, h: 277, scale: 0.6 },
  // Middle band — Dairon (center), Cataris (right, pulled closer to Dairon)
  { region: "dairon", x: 1056, y: 1313, w: 1080, h: 343, scale: 1 },
  { region: "cataris", x: 2250, y: 1235, w: 1080, h: 499, scale: 1 },
  // Lower band — Burenia (lower left, tall), Artaria (lower center, pulled up toward Dairon)
  { region: "burenia", x: 250, y: 1150, w: 809, h: 853, scale: 1 },
  { region: "artaria", x: 1436, y: 1760, w: 1080, h: 395, scale: 1 },
];

// Itorash slot — top area at fractional center (~0.61, 0.05); 200×120 slot.
const ITORASH = { x: 2218, y: 75, w: 200, h: 120 };

export default {
  name: "CombinedMap",
  components: { RegionTile },
  computed: {
    ...mapGetters("logic", ["seedBeatable"]),
  },
  data() {
    return {
      // Return a shallow copy so Vue's reactive proxy does not mutate the shared
      // module-level constant (IN-03: avoids coupling TILES to one component's
      // reactive graph across HMR reloads or multiple instances).
      tiles: TILES.map((t) => ({ ...t })),
      surfaceStyle: {
        width: SURFACE_W + "px",
        height: SURFACE_H + "px",
      },
      itorashStyle: {
        left: ITORASH.x + "px",
        top: ITORASH.y + "px",
        width: ITORASH.w + "px",
        height: ITORASH.h + "px",
        position: "absolute",
      },
      pz: null,
    };
  },
  mounted() {
    const surface = this.$refs.surface;
    const viewport = this.$refs.viewport;

    // Fit the whole overworld on initial load.
    // Compute a fit scale so the logical surface fits the viewport.
    const surfaceLogicalWidth = SURFACE_W;
    const surfaceLogicalHeight = SURFACE_H;
    const vpWidth = viewport.clientWidth || 1280;
    const vpHeight = viewport.clientHeight || 720;
    const fitScaleW = vpWidth / surfaceLogicalWidth;
    const fitScaleH = vpHeight / surfaceLogicalHeight;
    const fitScale = Math.min(fitScaleW, fitScaleH, 1);

    // Center the surface in the viewport at the fit scale.
    const scaledW = surfaceLogicalWidth * fitScale;
    const scaledH = surfaceLogicalHeight * fitScale;
    const offsetX = Math.max(0, (vpWidth - scaledW) / 2);
    const offsetY = Math.max(0, (vpHeight - scaledH) / 2);
    // Panzoom sets transform-origin: 50% 50% on HTML elements (see @panzoom/panzoom
    // src line: setStyle(elem, 'transformOrigin', '50% 50%')).  The CSS transform
    // applied is scale(s) translate(x px, y px) — transforms compose right-to-left,
    // so translate runs first in element-local space, then scale around the center.
    // Visual top-left of the element = cx*(1-s) + panX*s, where cx = SURFACE_W/2.
    // Solving for panX so that visual top-left == offsetX:
    //   panX = (offsetX - cx*(1-fitScale)) / fitScale
    // The old formula (offsetX/fitScale) was correct only when cx==0, which held
    // before the explicit SURFACE_W/H was added (a 0×0 element has center==origin).
    const cx = surfaceLogicalWidth / 2;
    const cy = surfaceLogicalHeight / 2;
    const panX = (offsetX - cx * (1 - fitScale)) / fitScale;
    const panY = (offsetY - cy * (1 - fitScale)) / fitScale;

    // Persist the fit view as non-reactive instance properties so resetView()
    // can restore it (WR-03). Stored outside data() to avoid Vue proxying them
    // and to sidestep the vue/no-reserved-keys lint rule.
    this.fitScale = fitScale;
    this.fitPanX = panX;
    this.fitPanY = panY;

    // Pass the computed fit as panzoom start values so pz.reset() also lands on
    // the correct view (WR-03).
    // canvas: true binds the pointerdown handler to the parent element (.map-viewport)
    // instead of .pan-surface. After the fit transform .pan-surface's rendered box is
    // smaller than the viewport, leaving empty letterbox margins where panning was not
    // captured. With canvas:true any drag anywhere in .map-viewport starts a pan.
    // panzoom-exclude on .zoom-controls (and marker toggle_boxes) prevents those
    // elements' pointerdown events from starting an unwanted pan drag.
    this.pz = Panzoom(surface, {
      canvas: true,
      maxScale: 5,
      minScale: 0.2,
      excludeClass: "panzoom-exclude",
      startScale: fitScale,
      startX: panX,
      startY: panY,
    });

    // Bind wheel zoom to the viewport (parent of the surface) for focal-point
    // zooming. { passive: false } is required because zoomWithWheel calls
    // event.preventDefault() — without it some engines ignore the call and
    // scroll the page instead of zooming (WR-04).
    this._wheelHandler = this.pz.zoomWithWheel;
    viewport.addEventListener("wheel", this._wheelHandler, { passive: false });
  },
  beforeUnmount() {
    if (this.pz) {
      const viewport = this.$refs.viewport;
      if (viewport && this._wheelHandler) {
        viewport.removeEventListener("wheel", this._wheelHandler);
      }
      this.pz.destroy();
      this.pz = null;
    }
  },
  methods: {
    _viewportCenter() {
      const rect = this.$refs.viewport.getBoundingClientRect();
      return {
        clientX: rect.left + rect.width / 2,
        clientY: rect.top + rect.height / 2,
      };
    },
    zoomIn() {
      if (!this.pz) return;
      // Zoom toward the viewport center so the content in view stays put.
      // Match panzoom's built-in step (Math.exp(0.3) ≈ 1.35x per click).
      const newScale = this.pz.getScale() * Math.exp(0.3);
      this.pz.zoomToPoint(newScale, this._viewportCenter());
    },
    zoomOut() {
      if (!this.pz) return;
      const newScale = this.pz.getScale() * Math.exp(-0.3);
      this.pz.zoomToPoint(newScale, this._viewportCenter());
    },
    resetView() {
      if (!this.pz) return;
      // Restore the computed fit view (not panzoom's hardcoded startScale:1 / startX:0
      // defaults) — WR-03. We pass startScale/startX/startY via Panzoom options above
      // so pz.reset() also works, but we call zoom+pan explicitly to be safe across
      // panzoom version differences.
      this.pz.zoom(this.fitScale, { animate: false });
      this.pz.pan(this.fitPanX, this.fitPanY, { animate: false });
    },
  },
};
</script>

